from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    store = OrderedDict()  # key -> (value, write_time)
    results = []

    def purge_expired(t):
        expired_keys = [k for k, (v, wt) in store.items() if wt + ttl <= t]
        for k in expired_keys:
            del store[k]

    for op in ops:
        kind = op[0]
        t = op[1]
        purge_expired(t)

        if kind == 'put':
            key = op[2]
            value = op[3]
            if key in store:
                # already present (not expired, since we purged)
                del store[key]
            else:
                if len(store) >= capacity:
                    # evict least recently used
                    store.popitem(last=False)
            store[key] = (value, t)
            store.move_to_end(key)
        elif kind == 'get':
            key = op[2]
            if key in store:
                value, wt = store[key]
                store.move_to_end(key)
                results.append(value)
            else:
                results.append(-1)
        else:
            raise ValueError(f"Unknown op type: {kind}")

    return results

